9	import { createMockDebtsSummary, defaultDebtsSummary } from '@/tests/mocks/data/money';
10	import { createMockPlayer } from '@/tests/mocks/data/player';
11	import type { PayDebtProxy } from '@/types/actions/PayDebt';
12	
13	const { refreshMock, notificationsShowMock, notificationsUpdateMock, captureUnexpectedErrorMock } = vi.hoisted(() => ({
14	    refreshMock: vi.fn(),
15	    notificationsShowMock: vi.fn(),
16	    notificationsUpdateMock: vi.fn(),
