29	}));
30	
31	const renderForm = (payDebt: PayDebtProxy) => {
32	    render(
33	        <Wrapper>
34	            <MoneyForm
35	                playerDebts={defaultDebtsSummary.players}
36	                payDebt={payDebt}
37	            />
