41	
42	describe('MoneyForm', () => {
43	    beforeEach(() => {
44	        vi.useFakeTimers({ shouldAdvanceTime: true });
45	        vi.clearAllMocks();
46	        vi.mocked(useRouter).mockReturnValue({
47	            push: vi.fn(),
48	            back: vi.fn(),
49	            forward: vi.fn(),
50	            refresh: refreshMock,
51	            replace: vi.fn(),
52	            prefetch: vi.fn(),
53	        });
54	    });
55	
56	    afterEach(() => {
57	        vi.clearAllTimers();
58	        vi.useRealTimers();
59	    });
60	
61	    it('renders unpaid player charges', () => {
62	        renderForm(vi.fn<PayDebtProxy>());
63	
64	        expect(screen.getByRole('heading', { name: 'Unpaid Player Charges' })).toBeInTheDocument();
65	        expect(screen.getByText('Alex Current')).toBeInTheDocument();
66	        expect(screen.getByText('Jamie Historic')).toBeInTheDocument();
67	    });
68	
69	    it('renders empty state when there are no debts', () => {
70	        render(
71	            <Wrapper>
72	                <MoneyForm
73	                    playerDebts={[]}
74	                    payDebt={vi.fn<PayDebtProxy>()}
75	                />
76	            </Wrapper>,
77	        );
78	
79	        expect(screen.queryByRole('button', { name: 'Paid' })).not.toBeInTheDocument();
80	    });
81	
82	    it('submits payment with multiple gameDayIds, updates notifications, and refreshes', async () => {
83	        const user = userEvent.setup();
84	        const payDebt = vi.fn<PayDebtProxy>().mockResolvedValue({
85	            playerId: 21,
86	            transactionIds: [777, 778],
87	            amount: 1225,
88	            resultingBalance: 0,
89	        });
90	
91	        renderForm(payDebt);
92	
93	        await user.click(screen.getAllByRole('button', { name: 'Paid' })[0]);
94	
